def restock(event, ctx):
    result = BatchResult()
    for record in event.records:
        item = record.json()
        if "qty" not in item:
            ctx.logger.error("restock without qty", extra={"message_id": record.id})
            result.fail(record)
            continue
        ctx.logger.info("restock", extra={"sku": item["sku"], "qty": item["qty"]})
    return result
